# Global variable for blocked slot testing
created_blocked_slot_id = None

def test_create_blocked_slot_manager():
    """Test POST /api/blocked-slots with manager authentication"""
    global created_blocked_slot_id
    if not manager_token:
        results.log_failure("Create Blocked Slot (Manager)", "No manager token available")
        return False
    
    try:
        # Get today's date for blocking
        today = datetime.now().strftime("%Y-%m-%d")
        
        blocked_slot_data = {
            "date": today,
            "time": "16:30",  # 4:30 PM
            "reason": "Staff meeting - testing blocked slots visibility"
        }
        
        headers = {"Authorization": f"Bearer {manager_token}"}
        response = requests.post(f"{API_URL}/blocked-slots", json=blocked_slot_data, headers=headers)
        
        if response.status_code == 200:
            data = response.json()
            if (data.get("date") == today and 
                data.get("time") == "16:30" and
                data.get("reason") == "Staff meeting - testing blocked slots visibility" and
                data.get("blocked_by_name") and
                "id" in data):
                created_blocked_slot_id = data["id"]
                results.log_success("Create Blocked Slot (Manager Authentication)")
                return True
        elif response.status_code == 400 and "already blocked" in response.json().get("detail", ""):
            results.log_success("Create Blocked Slot (Manager - Already Blocked)")
            # Try to get existing blocked slots to find the ID
            get_response = requests.get(f"{API_URL}/blocked-slots/{today}", headers=headers)
            if get_response.status_code == 200:
                blocked_slots = get_response.json()
                for slot in blocked_slots:
                    if slot.get("time") == "16:30":
                        created_blocked_slot_id = slot["id"]
                        break
            return True
        results.log_failure("Create Blocked Slot (Manager)", f"Status: {response.status_code}, Response: {response.text}")
        return False
    except Exception as e:
        results.log_failure("Create Blocked Slot (Manager)", str(e))
        return False

