def test_blocked_slot_data_structure():
    """Test that blocked slots have proper data structure: is_blocked=true, blocked_info with id, reason, blocked_by, blocked_at"""
    if not manager_token:
        results.log_failure("Blocked Slot Data Structure", "No manager token available")
        return False
    
    try:
        today = datetime.now().strftime("%Y-%m-%d")
        headers = {"Authorization": f"Bearer {manager_token}"}
        response = requests.get(f"{API_URL}/urgent-care-time-slots/{today}", headers=headers)
        
        if response.status_code == 200:
            data = response.json()
            if data.get("available") and "slots" in data:
                blocked_slots_found = []
                for slot in data["slots"]:
                    if slot.get("is_blocked") == True:
                        blocked_slots_found.append(slot)
                        
                        # Verify complete data structure
                        required_fields = ["is_blocked", "blocked_info"]
                        blocked_info_fields = ["id", "reason", "blocked_by", "blocked_at"]
                        
                        # Check main fields
                        for field in required_fields:
                            if field not in slot:
                                results.log_failure("Blocked Slot Data Structure", f"Missing field: {field}")
                                return False
                        
                        # Check blocked_info fields
                        blocked_info = slot.get("blocked_info", {})
                        for field in blocked_info_fields:
                            if field not in blocked_info:
                                results.log_failure("Blocked Slot Data Structure", f"Missing blocked_info field: {field}")
                                return False
                        
                        # Verify data types and values
                        if slot["is_blocked"] != True:
                            results.log_failure("Blocked Slot Data Structure", "is_blocked should be True")
                            return False
                        
                        if not isinstance(blocked_info["id"], str) or not blocked_info["id"]:
                            results.log_failure("Blocked Slot Data Structure", "blocked_info.id should be non-empty string")
                            return False
                
                if blocked_slots_found:
                    results.log_success("Blocked Slot Data Structure (Complete and Valid)")
                    return True
                else:
                    results.log_failure("Blocked Slot Data Structure", "❌ CRITICAL: No blocked slots found to verify data structure!")
                    return False
            elif not data.get("available"):
                results.log_success("Blocked Slot Data Structure (Day Closed - Cannot Test)")
                return True
        results.log_failure("Blocked Slot Data Structure", f"Status: {response.status_code}, Response: {response.text}")
        return False
    except Exception as e:
        results.log_failure("Blocked Slot Data Structure", str(e))
        return False

