def test_ai_agents_comprehensive_analysis():
    """Comprehensive analysis of AI agents for dashboard functionality"""
    if not admin_token:
        results.log_failure("AI Agents - Comprehensive Analysis", "No admin token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {admin_token}"}
        response = requests.get(f"{API_URL}/ai-agents", headers=headers)
        
        if response.status_code == 200:
            agents = response.json()
            
            print(f"\n🔍 COMPREHENSIVE AI AGENTS DASHBOARD ANALYSIS")
            print(f"=" * 60)
            print(f"Total Agents Found: {len(agents)}")
            
            # Categorize agents by mode
            mode_counts = {}
            recurring_agents = []
            write_mode_agents = []
            agents_with_next_run_fields = []
            
            for agent in agents:
                # Get mode (check both 'mode' and 'workflow_mode' fields)
                agent_mode = agent.get("mode") or agent.get("workflow_mode", "unknown")
                mode_counts[agent_mode] = mode_counts.get(agent_mode, 0) + 1
                
                # Check for recurring agents
                if agent.get("recurring") == True:
                    recurring_agents.append(agent)
                
                # Check for write mode agents
                if agent_mode == "write":
                    write_mode_agents.append(agent)
                
                # Check for next run calculation fields
                has_scheduling_fields = any([
                    agent.get("post_time"),
                    agent.get("days_of_week"),
                    agent.get("last_manual_run")
                ])
                
                if has_scheduling_fields:
                    agents_with_next_run_fields.append(agent)
            
            print(f"\nAgent Modes Distribution:")
            for mode, count in mode_counts.items():
                print(f"  - {mode}: {count} agents")
            
            print(f"\nRecurring Agents: {len(recurring_agents)}")
            print(f"Write Mode Agents: {len(write_mode_agents)}")
            print(f"Agents with Next Run Fields: {len(agents_with_next_run_fields)}")
            
            # Check for Write Mode + Recurring combination
            write_recurring = [a for a in agents if a.get("mode") == "write" and a.get("recurring") == True]
            print(f"Write Mode + Recurring: {len(write_recurring)} agents")
            
            # Check for agents that would show "Next Run & Last Run" section
            next_run_candidates = []
            for agent in agents:
                agent_mode = agent.get("mode") or agent.get("workflow_mode")
                is_recurring = agent.get("recurring") == True
                has_schedule_data = any([
                    agent.get("post_time"),
                    agent.get("days_of_week")
                ])
                
                if (agent_mode in ["write", "recurring", "auto"] and is_recurring) or has_schedule_data:
                    next_run_candidates.append(agent)
            
            print(f"\nAgents that would show 'Next Run & Last Run' section: {len(next_run_candidates)}")
            
            if next_run_candidates:
                print(f"\nNext Run Candidates Details:")
                for i, agent in enumerate(next_run_candidates[:5], 1):  # Show first 5
                    print(f"  {i}. {agent.get('name', 'Unnamed')} (Mode: {agent.get('mode') or agent.get('workflow_mode', 'N/A')})")
                    print(f"     - Recurring: {agent.get('recurring')}")
                    print(f"     - Post Time: {agent.get('post_time', 'N/A')}")
                    print(f"     - Days of Week: {agent.get('days_of_week', 'N/A')}")
                if len(next_run_candidates) > 5:
                    print(f"     ... and {len(next_run_candidates) - 5} more")
            
            results.log_success("AI Agents - Comprehensive Analysis")
            return {
                'total_agents': len(agents),
                'mode_counts': mode_counts,
                'recurring_agents': len(recurring_agents),
                'write_mode_agents': len(write_mode_agents),
                'next_run_candidates': len(next_run_candidates),
                'agents_with_scheduling': len(agents_with_next_run_fields)
            }
        else:
            results.log_failure("AI Agents - Comprehensive Analysis", f"Status: {response.status_code}")
            return False
    except Exception as e:
        results.log_failure("AI Agents - Comprehensive Analysis", str(e))
        return False

