def test_investigate_employee_data_structure():
    """Investigate GET /api/employees - Check employee data structure and name field"""
    if not manager_token:
        results.log_failure("Investigate Employee Data Structure", "No manager token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {manager_token}"}
        response = requests.get(f"{API_URL}/employees", headers=headers)
        
        if response.status_code == 200:
            data = response.json()
            print(f"\n🔍 EMPLOYEE DATA STRUCTURE INVESTIGATION:")
            print(f"Total employees found: {len(data) if isinstance(data, list) else 'Not a list'}")
            
            if isinstance(data, list) and len(data) > 0:
                # Examine first employee record
                first_employee = data[0]
                print(f"\nFirst employee record structure:")
                for key, value in first_employee.items():
                    print(f"  {key}: {value} (type: {type(value).__name__})")
                
                # Check what field contains the employee name
                name_fields = []
                for key in first_employee.keys():
                    if 'name' in key.lower():
                        name_fields.append(key)
                        print(f"  📝 NAME FIELD FOUND: {key} = {first_employee[key]}")
                
                if not name_fields:
                    print(f"  ❌ NO NAME FIELDS FOUND! Available fields: {list(first_employee.keys())}")
                
                # Check if any field contains UUID-like values (the reported issue)
                uuid_like_fields = []
                for key, value in first_employee.items():
                    if isinstance(value, str) and len(value) == 36 and value.count('-') == 4:
                        uuid_like_fields.append((key, value))
                        print(f"  🆔 UUID-LIKE FIELD: {key} = {value}")
                
                results.log_success("Investigate Employee Data Structure - Data Retrieved")
                return True
            else:
                print(f"  ❌ No employee data found or invalid format")
                results.log_failure("Investigate Employee Data Structure", "No employee data found")
                return False
        else:
            results.log_failure("Investigate Employee Data Structure", f"Status: {response.status_code}, Response: {response.text}")
            return False
    except Exception as e:
        results.log_failure("Investigate Employee Data Structure", str(e))
        return False

