def test_cross_reference_employee_names_with_ids():
    """Cross-reference employee IDs from AI agents with actual employee names"""
    if not manager_token:
        results.log_failure("Cross Reference Employee Names", "No manager token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {manager_token}"}
        
        # Get employees list
        employees_response = requests.get(f"{API_URL}/employees", headers=headers)
        if employees_response.status_code != 200:
            results.log_failure("Cross Reference Employee Names", "Failed to get employees")
            return False
        
        employees = employees_response.json()
        
        # Get AI agents
        agents_response = requests.get(f"{API_URL}/ai-agents", headers=headers)
        if agents_response.status_code != 200:
            results.log_failure("Cross Reference Employee Names", "Failed to get AI agents")
            return False
        
        agents = agents_response.json()
        
        print(f"\n🔗 CROSS-REFERENCE ANALYSIS:")
        
        # Create employee lookup map
        employee_map = {}
        if isinstance(employees, list):
            for emp in employees:
                emp_id = emp.get('id') or emp.get('user_id')
                emp_name = emp.get('full_name') or emp.get('name') or emp.get('first_name', '') + ' ' + emp.get('last_name', '')
                if emp_id:
                    employee_map[emp_id] = emp_name.strip()
            
            print(f"Employee lookup map created with {len(employee_map)} entries:")
            for emp_id, emp_name in employee_map.items():
                print(f"  {emp_id} -> {emp_name}")
        
        # Check timesheet agents
        if isinstance(agents, list):
            timesheet_agents = [agent for agent in agents if agent.get('agent_type') == 'time_sheet']
            
            for agent in timesheet_agents:
                selected_employees = agent.get('selected_employees', [])
                print(f"\nAgent '{agent.get('name')}' selected employees:")
                
                for emp_id in selected_employees:
                    emp_name = employee_map.get(emp_id, "❌ NAME NOT FOUND")
                    print(f"  {emp_id} -> {emp_name}")
                    
                    if emp_name == "❌ NAME NOT FOUND":
                        print(f"    ❌ MAPPING ISSUE: Employee ID {emp_id} not found in employees list!")
        
        results.log_success("Cross Reference Employee Names - Analysis Complete")
        return True
        
    except Exception as e:
        results.log_failure("Cross Reference Employee Names", str(e))
        return False

def test_next_run_date_calculation_investigation():
    """Investigate next run date calculation for timesheet agents"""
    if not manager_token:
        results.log_failure("Next Run Date Calculation Investigation", "No manager token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {manager_token}"}
        
        # Get timesheet config for foundation date
        config_response = requests.get(f"{API_URL}/timesheet-config", headers=headers)
        if config_response.status_code != 200:
            results.log_failure("Next Run Date Calculation Investigation", "Failed to get timesheet config")
            return False
        
        config = config_response.json()
        foundation_date = config.get('original_pay_period_start_date')
        
        # Get AI agents
        agents_response = requests.get(f"{API_URL}/ai-agents", headers=headers)
        if agents_response.status_code != 200:
            results.log_failure("Next Run Date Calculation Investigation", "Failed to get AI agents")
            return False
        
        agents = agents_response.json()
        
        print(f"\n📅 NEXT RUN DATE CALCULATION INVESTIGATION:")
        print(f"Foundation date from config: {foundation_date}")
        
        if isinstance(agents, list):
            timesheet_agents = [agent for agent in agents if agent.get('agent_type') == 'time_sheet']
            
            for agent in timesheet_agents:
                print(f"\nAgent: {agent.get('name')}")
                print(f"  Frequency: {agent.get('frequency')}")
                print(f"  Next Run Date: {agent.get('next_run_date')}")
                print(f"  Created At: {agent.get('created_at')}")
                
                # Check if next_run_date looks calculated or just a placeholder
                next_run = agent.get('next_run_date')
                if next_run:
                    try:
                        from datetime import datetime
                        parsed_next_run = datetime.fromisoformat(next_run.replace('Z', ''))
                        print(f"  Parsed Next Run: {parsed_next_run}")
                        
                        # Check if it's based on foundation date
                        if foundation_date:
                            parsed_foundation = datetime.fromisoformat(foundation_date.replace('Z', ''))
                            print(f"  Foundation Date: {parsed_foundation}")
                            
                            # Calculate expected next run based on frequency
                            frequency = agent.get('frequency')
                            if frequency == 'weekly':
                                print(f"  Expected calculation: Foundation + weekly intervals")
                            elif frequency == 'biweekly':
                                print(f"  Expected calculation: Foundation + biweekly intervals")
                            elif frequency == 'monthly':
                                print(f"  Expected calculation: Foundation + monthly intervals")
                        else:
                            print(f"  ❌ Cannot calculate without foundation date!")
                            
                    except Exception as parse_error:
                        print(f"  ❌ Date parsing failed: {parse_error}")
                else:
                    print(f"  ❌ No next run date set!")
        
        results.log_success("Next Run Date Calculation Investigation - Analysis Complete")
        return True
        
    except Exception as e:
        results.log_failure("Next Run Date Calculation Investigation", str(e))
        return False

