def test_timesheet_config_bson_encoding_fix():
    """Test that BSON encoding error is fixed - no datetime.date objects causing errors"""
    if not manager_token:
        results.log_failure("BSON Encoding Fix Test", "No manager token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {manager_token}"}
        
        # Test multiple date updates to ensure no BSON encoding errors
        test_dates = ["2024-01-01", "2024-06-15", "2024-12-31"]
        
        for test_date in test_dates:
            update_data = {
                "location_tracking_enabled": True,
                "after_hours_cutoff_time": "17:00",
                "auto_clockout_grace_minutes": 30,
                "pay_period_type": "biweekly",
                "original_pay_period_start_date": test_date
            }
            
            response = requests.put(f"{API_URL}/timesheet-config", json=update_data, headers=headers)
            
            if response.status_code != 200:
                # Check if it's the old BSON encoding error
                if "bson.errors.InvalidDocument" in response.text or "cannot encode object" in response.text:
                    results.log_failure("BSON Encoding Fix Test", 
                                      f"❌ BSON encoding error still exists for date {test_date}: {response.text}")
                    return False
                else:
                    results.log_failure("BSON Encoding Fix Test", 
                                      f"Unexpected error for date {test_date}: Status {response.status_code}, Response: {response.text}")
                    return False
            
            # Verify the date was saved correctly
            data = response.json()
            if data.get("original_pay_period_start_date") != test_date:
                results.log_failure("BSON Encoding Fix Test", 
                                  f"Date mismatch for {test_date}: got '{data.get('original_pay_period_start_date')}'")
                return False
        
        results.log_success("BSON Encoding Fix Test (No BSON Errors - String Format Working)")
        return True
    except Exception as e:
        results.log_failure("BSON Encoding Fix Test", str(e))
        return False

