def test_timesheet_agent_cross_collection_access():
    """Test accessing timesheet agents across different collections"""
    # Try admin token first, then manager token
    token = admin_token if admin_token else manager_token
    if not token:
        results.log_failure("Timesheet Agent Cross Collection Access", "No admin or manager token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {token}"}
        
        print("\n🔄 TESTING CROSS-COLLECTION ACCESS:")
        print("=" * 50)
        
        # Get all agents from both collections
        ai_agents_response = requests.get(f"{API_URL}/ai-agents", headers=headers)
        timesheet_agents_response = requests.get(f"{API_URL}/timesheet-ai-agents", headers=headers)
        
        if ai_agents_response.status_code != 200 or timesheet_agents_response.status_code != 200:
            results.log_failure("Cross Collection Access", "Failed to fetch from one or both collections")
            return False
        
        ai_agents = ai_agents_response.json()
        timesheet_agents = timesheet_agents_response.json()
        
        # Find timesheet agents in ai_agents collection
        timesheet_in_ai = [agent for agent in ai_agents if agent.get("agent_type") == "time_sheet"]
        
        print(f"Timesheet agents in ai_agents: {len(timesheet_in_ai)}")
        print(f"Agents in timesheet_ai_agents: {len(timesheet_agents)}")
        
        # Test updating each timesheet agent found in ai_agents via timesheet endpoint
        update_failures = []
        update_successes = []
        
        for agent in timesheet_in_ai:
            agent_id = agent.get("id")
            print(f"\nTesting update for agent {agent_id} ({agent.get('name')}):")
            
            update_data = {
                "name": f"Updated {agent.get('name')} - Cross Collection Test",
                "selected_employees": agent.get("selected_employees", []),
                "email_recipients": agent.get("email_recipients", [])
            }
            
            response = requests.put(f"{API_URL}/timesheet-ai-agents/{agent_id}", json=update_data, headers=headers)
            
            if response.status_code == 200:
                print(f"   ✅ Update successful")
                update_successes.append(agent_id)
            elif response.status_code == 404:
                print(f"   ❌ Agent not found in timesheet collection")
                update_failures.append(agent_id)
            else:
                print(f"   ❌ Update failed: {response.status_code}")
                update_failures.append(agent_id)
        
        print(f"\n📊 RESULTS:")
        print(f"   Successful updates: {len(update_successes)}")
        print(f"   Failed updates (not found): {len(update_failures)}")
        
        if update_failures:
            results.log_failure("Cross Collection Access", f"❌ CONFIRMED BUG: {len(update_failures)} timesheet agents in ai_agents cannot be updated via timesheet-ai-agents endpoint")
            return False
        else:
            results.log_success("Cross Collection Access - All timesheet agents accessible")
            return True
            
    except Exception as e:
        results.log_failure("Timesheet Agent Cross Collection Access", str(e))
        return False

