def test_get_pay_period_settings():
    """Test GET /api/pay-period-settings - Verify labels don't duplicate"""
    if not manager_token:
        results.log_failure("Get Pay Period Settings", "No manager token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {manager_token}"}
        response = requests.get(f"{API_URL}/pay-period-settings", headers=headers)
        
        if response.status_code == 200:
            data = response.json()
            if isinstance(data, list):
                # Check for proper label format (should not duplicate like "Weekly - Weekly")
                for setting in data:
                    config_name = setting.get("config_name", "")
                    if setting.get("period_type") == "weekly":
                        # Should be "Weekly - Monday to Friday", not "Weekly - Weekly"
                        if "Weekly - Monday to Friday" in config_name and "Weekly - Weekly" not in config_name:
                            results.log_success("Get Pay Period Settings (Labels Not Duplicated)")
                            return True
                        elif "Weekly" in config_name:
                            # Found weekly setting, check if it has proper format
                            if config_name.count("Weekly") == 1:
                                results.log_success("Get Pay Period Settings (Weekly Label Format Correct)")
                                return True
                            else:
                                results.log_failure("Get Pay Period Settings", f"❌ LABEL DUPLICATION BUG: Found '{config_name}' - labels are duplicated!")
                                return False
                
                results.log_success("Get Pay Period Settings (Retrieved Successfully)")
                return True
        results.log_failure("Get Pay Period Settings", f"Status: {response.status_code}, Response: {response.text}")
        return False
    except Exception as e:
        results.log_failure("Get Pay Period Settings", str(e))
        return False

def test_update_pay_period_setting():
    """Test PUT /api/pay-period-settings/{id} - Update pay period setting"""
    if not manager_token:
        results.log_failure("Update Pay Period Setting", "No manager token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {manager_token}"}
        
        # First get existing settings to find one to update
        response = requests.get(f"{API_URL}/pay-period-settings", headers=headers)
        if response.status_code != 200:
            results.log_failure("Update Pay Period Setting (Setup)", "Failed to get existing settings")
            return False
        
        settings = response.json()
        if not settings:
            results.log_failure("Update Pay Period Setting", "No existing settings to update")
            return False
        
        # Find a non-default setting to update
        setting_to_update = None
        for setting in settings:
            if not setting.get("is_default", False):
                setting_to_update = setting
                break
        
        if not setting_to_update:
            # Use the first setting
            setting_to_update = settings[0]
        
        setting_id = setting_to_update["id"]
        
        # Update the setting
        update_data = {
            "config_name": f"Updated - {setting_to_update.get('config_name', 'Test Setting')}"
        }
        
        response = requests.put(f"{API_URL}/pay-period-settings/{setting_id}", json=update_data, headers=headers)
        
        if response.status_code == 200:
            data = response.json()
            if "message" in data and "updated successfully" in data["message"]:
                results.log_success("Update Pay Period Setting")
                return True
        results.log_failure("Update Pay Period Setting", f"Status: {response.status_code}, Response: {response.text}")
        return False
    except Exception as e:
        results.log_failure("Update Pay Period Setting", str(e))
        return False

