def test_timesheet_agent_generates_reports_not_posts():
    """Test that timesheet agents generate timesheet reports, not social media posts"""
    if not admin_token:
        results.log_failure("Timesheet Agent Report Generation", "No admin token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {admin_token}"}
        
        # Create a new timesheet agent for this test
        agent_data = {
            "agent_type": "time_sheet",
            "agent_name": "Test Report Generation Agent",
            "mode": "adhoc",
            "topic": "timesheet_report",  # Required by current validation logic
            "selected_employees": [],
            "report_period": "current_week",
            "include_summary": True,
            "include_billing_rates": True,
            "initial_status": "in_review",
            "email_recipients": [],
            "image_option": "none",
            "word_count": "100",
            "social_platforms": {
                "facebook": True,  # Required by current validation logic
                "instagram": False,
                "twitter": False,
                "whatsapp": False
            }
        }
        
        # Create agent
        create_response = requests.post(f"{API_URL}/ai-agents", json=agent_data, headers=headers)
        if create_response.status_code != 200:
            results.log_failure("Timesheet Agent Report Generation (Setup)", f"Failed to create test agent: {create_response.status_code}")
            return False
        
        test_agent_id = create_response.json()["agent_id"]
        
        # Run the agent
        run_response = requests.post(f"{API_URL}/ai-agents/{test_agent_id}/run", headers=headers)
        if run_response.status_code != 200:
            results.log_failure("Timesheet Agent Report Generation", f"Failed to run agent: {run_response.status_code}")
            return False
        
        # Check that it generates timesheet reports, not AI posts
        # Wait a moment for processing
        time.sleep(2)
        
        # Check timesheet reports
        reports_response = requests.get(f"{API_URL}/timesheet-reports", headers=headers)
        
        # Check AI posts (should not have new posts from timesheet agent)
        posts_response = requests.get(f"{API_URL}/ai-posts/ready-to-publish", headers=headers)
        
        # Clean up test agent
        requests.delete(f"{API_URL}/ai-agents/{test_agent_id}", headers=headers)
        
        if reports_response.status_code == 200:
            results.log_success("Timesheet Agent Report Generation (Generates Reports)")
            return True
        else:
            results.log_failure("Timesheet Agent Report Generation", f"Reports endpoint failed: {reports_response.status_code}")
            return False
            
    except Exception as e:
        results.log_failure("Timesheet Agent Report Generation", str(e))
        return False

