def test_pin_validation_various_symbols():
    """Test PIN validation with various symbol combinations: !@#$%&*"""
    if not manager_token:
        results.log_failure("PIN Validation (Various Symbols)", "No manager token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {manager_token}"}
        
        # Test different symbol combinations
        test_pins = [
            "Pass1!",   # 6 chars with !
            "Test2@",   # 6 chars with @
            "Code3#",   # 6 chars with #
            "Work4$",   # 6 chars with $
            "Safe5%",   # 6 chars with %
            "Lock6&",   # 6 chars with &
            "Star7*",   # 6 chars with *
            "Mix!@#123" # 9 chars with multiple symbols
        ]
        
        successful_pins = 0
        
        for i, pin in enumerate(test_pins):
            employee_data = {
                "email": f"employee_symbol_{i}_{int(time.time())}@veterinary.com",
                "full_name": f"Symbol Test Employee {i}",
                "role": "user",
                "pin": pin
            }
            
            response = requests.post(f"{API_URL}/employees", json=employee_data, headers=headers)
            
            if response.status_code == 200:
                data = response.json()
                if data.get("pin") == pin:
                    successful_pins += 1
            else:
                print(f"  Failed PIN '{pin}': {response.status_code} - {response.text}")
        
        if successful_pins == len(test_pins):
            results.log_success("PIN Validation (Various Symbols - All Accepted)")
            return True
        elif successful_pins > 0:
            results.log_success(f"PIN Validation (Various Symbols - {successful_pins}/{len(test_pins)} Accepted)")
            return True
        else:
            results.log_failure("PIN Validation (Various Symbols)", "No symbol PINs were accepted")
            return False
    except Exception as e:
        results.log_failure("PIN Validation (Various Symbols)", str(e))
        return False

