def test_get_all_time_entries_proper_structure():
    """Test GET /api/timesheet/all-entries returns time entries with proper structure"""
    if not manager_token:
        results.log_failure("Get All Time Entries (Structure Validation)", "No manager token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {manager_token}"}
        
        from datetime import timedelta
        start_date = (datetime.now() - timedelta(days=30)).strftime("%Y-%m-%d")
        end_date = datetime.now().strftime("%Y-%m-%d")
        
        params = {
            "start_date": start_date,
            "end_date": end_date
        }
        
        response = requests.get(f"{API_URL}/timesheet/all-entries", headers=headers, params=params)
        if response.status_code == 200:
            data = response.json()
            if isinstance(data, list):
                # Verify structure of time entries
                required_fields = ["id", "user_id", "clock_in_time", "status", "created_at"]
                
                if len(data) > 0:
                    # Check first entry structure
                    entry = data[0]
                    for field in required_fields:
                        if field not in entry:
                            results.log_failure("Get All Time Entries (Structure Validation)", f"Missing required field: {field}")
                            return False
                    
                    # Verify status field exists (important for adjustments)
                    if "status" not in entry:
                        results.log_failure("Get All Time Entries (Structure Validation)", "Missing status field")
                        return False
                
                results.log_success("Get All Time Entries (Structure Validation)")
                return True
        results.log_failure("Get All Time Entries (Structure Validation)", f"Status: {response.status_code}, Response: {response.text}")
        return False
    except Exception as e:
        results.log_failure("Get All Time Entries (Structure Validation)", str(e))
        return False

