# Global variable for created employee
created_employee_id = None

def test_create_employee_manager():
    """Test POST /api/employees with manager token"""
    global created_employee_id
    if not manager_token:
        results.log_failure("Create Employee (Manager)", "No manager token available")
        return False
    
    try:
        employee_data = {
            "email": "newemployee@veterinary.com",
            "password": "employee123",
            "full_name": "Dr. Jane Smith",
            "role": "technician"
        }
        
        headers = {"Authorization": f"Bearer {manager_token}"}
        response = requests.post(f"{API_URL}/employees", json=employee_data, headers=headers)
        if response.status_code == 200:
            data = response.json()
            if (data.get("email") == employee_data["email"] and 
                data.get("full_name") == employee_data["full_name"] and
                data.get("role") == employee_data["role"] and
                "id" in data):
                created_employee_id = data["id"]
                results.log_success("Create Employee (Manager)")
                return True
        elif response.status_code == 400 and "already registered" in response.json().get("detail", ""):
            # Employee already exists, get their ID for other tests
            headers = {"Authorization": f"Bearer {manager_token}"}
            employees_response = requests.get(f"{API_URL}/employees", headers=headers)
            if employees_response.status_code == 200:
                employees = employees_response.json()
                for emp in employees:
                    if emp.get("email") == employee_data["email"]:
                        created_employee_id = emp["id"]
                        break
            results.log_success("Create Employee (Manager - Already Exists)")
            return True
        results.log_failure("Create Employee (Manager)", f"Status: {response.status_code}, Response: {response.text}")
        return False
    except Exception as e:
        results.log_failure("Create Employee (Manager)", str(e))
        return False

