def test_ai_posts_ready_to_publish_api():
    """Test GET /api/ai-posts/ready-to-publish endpoint with pagination and filtering"""
    if not admin_token:
        results.log_failure("AI Posts Ready-to-Publish API", "No admin token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {admin_token}"}
        
        # Test basic endpoint with pagination parameters
        response = requests.get(f"{API_URL}/ai-posts/ready-to-publish?page=1&limit=10", headers=headers)
        
        if response.status_code == 200:
            data = response.json()
            # Verify response structure for pagination
            if (isinstance(data, dict) and 
                "posts" in data and 
                "pagination" in data and
                isinstance(data["posts"], list) and
                isinstance(data["pagination"], dict)):
                
                # Verify pagination structure
                pagination = data["pagination"]
                required_pagination_fields = ["current_page", "total_pages", "total_count", "limit", "has_next", "has_prev"]
                if all(field in pagination for field in required_pagination_fields):
                    results.log_success("AI Posts Ready-to-Publish API (Pagination Structure)")
                    return True
                else:
                    results.log_failure("AI Posts Ready-to-Publish API", f"Missing pagination fields: {[f for f in required_pagination_fields if f not in pagination]}")
                    return False
            else:
                results.log_failure("AI Posts Ready-to-Publish API", f"Invalid response structure: {data}")
                return False
        else:
            results.log_failure("AI Posts Ready-to-Publish API", f"Status: {response.status_code}, Response: {response.text}")
            return False
    except Exception as e:
        results.log_failure("AI Posts Ready-to-Publish API", str(e))
        return False

