def test_ai_posts_ready_to_publish_authentication():
    """Test authentication requirements for ready-to-publish endpoint"""
    try:
        # Test without authentication
        response = requests.get(f"{API_URL}/ai-posts/ready-to-publish?page=1&limit=10")
        
        if response.status_code in [401, 403]:
            results.log_success("AI Posts Ready-to-Publish Authentication (No Auth)")
        else:
            results.log_failure("AI Posts Ready-to-Publish Authentication", f"Expected 401/403, got {response.status_code}")
            return False
        
        # Test with regular user token (should fail)
        if user_token:
            headers = {"Authorization": f"Bearer {user_token}"}
            response = requests.get(f"{API_URL}/ai-posts/ready-to-publish?page=1&limit=10", headers=headers)
            
            if response.status_code == 403:
                results.log_success("AI Posts Ready-to-Publish Authentication (Regular User Forbidden)")
                return True
            else:
                results.log_failure("AI Posts Ready-to-Publish Authentication", f"Regular user should get 403, got {response.status_code}")
                return False
        else:
            results.log_success("AI Posts Ready-to-Publish Authentication (No Regular User Token)")
            return True
            
    except Exception as e:
        results.log_failure("AI Posts Ready-to-Publish Authentication", str(e))
        return False

def test_ai_posts_data_structure_topic_field():
    """Test that posts returned by API include topic field for frontend pre-population"""
    if not admin_token:
        results.log_failure("AI Posts Data Structure Topic Field", "No admin token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {admin_token}"}
        
        # Get ready-to-publish posts to check data structure
        response = requests.get(f"{API_URL}/ai-posts/ready-to-publish?page=1&limit=5", headers=headers)
        
        if response.status_code == 200:
            data = response.json()
            if "posts" in data and isinstance(data["posts"], list):
                posts = data["posts"]
                
                if len(posts) > 0:
                    # Check if posts have required fields for frontend
                    first_post = posts[0]
                    required_fields = ["id", "topic", "content", "image_text"]
                    
                    missing_fields = [field for field in required_fields if field not in first_post]
                    if not missing_fields:
                        results.log_success("AI Posts Data Structure Topic Field (All Required Fields Present)")
                        return True
                    else:
                        results.log_failure("AI Posts Data Structure Topic Field", f"Missing fields in post data: {missing_fields}")
                        return False
                else:
                    results.log_success("AI Posts Data Structure Topic Field (No Posts to Check)")
                    return True
            else:
                results.log_failure("AI Posts Data Structure Topic Field", f"Invalid posts structure: {data}")
                return False
        else:
            results.log_failure("AI Posts Data Structure Topic Field", f"Status: {response.status_code}, Response: {response.text}")
            return False
    except Exception as e:
        results.log_failure("AI Posts Data Structure Topic Field", str(e))
        return False

