def test_ai_posts_regenerate_content_admin():
    """Test POST /api/ai-posts/{post_id}/regenerate-content endpoint with admin credentials"""
    if not admin_token:
        results.log_failure("AI Posts Regenerate Content (Admin)", "No admin token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {admin_token}"}
        
        # First, get a post to regenerate content for
        response = requests.get(f"{API_URL}/ai-posts/ready-to-publish?page=1&limit=1", headers=headers)
        
        if response.status_code == 200:
            data = response.json()
            if "posts" in data and len(data["posts"]) > 0:
                post = data["posts"][0]
                post_id = post["id"]
                current_content = post.get("content", "Sample veterinary content about pet health and wellness.")
                topic = post.get("topic", "Pet Health")
                
                # Test regenerating content
                content_data = {
                    "current_content": current_content,
                    "topic": topic
                }
                
                response = requests.post(f"{API_URL}/ai-posts/{post_id}/regenerate-content", json=content_data, headers=headers)
                
                if response.status_code == 200:
                    result = response.json()
                    if ("message" in result and 
                        "new_content" in result and 
                        "original_content" in result and
                        result["new_content"] != result["original_content"] and
                        len(result["new_content"]) > 10):  # Ensure meaningful content was generated
                        results.log_success("AI Posts Regenerate Content (Admin - Working)")
                        return True
                    else:
                        results.log_failure("AI Posts Regenerate Content (Admin)", f"Invalid response structure: {result}")
                        return False
                elif response.status_code == 500:
                    # Check if it's an AI service configuration issue
                    result = response.json()
                    error_detail = result.get("detail", "")
                    if "Failed to generate new content" in error_detail:
                        results.log_failure("AI Posts Regenerate Content (Admin)", f"❌ REGENERATE CONTENT FAILED: {error_detail}. Check if AI service is properly configured or if there are LlmChat initialization issues.")
                        return False
                    else:
                        results.log_failure("AI Posts Regenerate Content (Admin)", f"Server error: {error_detail}")
                        return False
                else:
                    results.log_failure("AI Posts Regenerate Content (Admin)", f"Unexpected status: {response.status_code}, Response: {response.text}")
                    return False
            else:
                results.log_success("AI Posts Regenerate Content (Admin - No Posts to Test)")
                return True
        else:
            results.log_failure("AI Posts Regenerate Content (Admin)", f"Failed to get posts for testing: {response.status_code}")
            return False
    except Exception as e:
        results.log_failure("AI Posts Regenerate Content (Admin)", str(e))
        return False

