        # Use a dummy post ID for authentication testing
        dummy_post_id = "test-post-id-12345"
        content_data = {
            "current_content": "Regular user trying to regenerate content",
            "topic": "This should be forbidden"
        }
        
        # Try with regular user token (should fail)
        headers = {"Authorization": f"Bearer {user_token}"}
        response = requests.post(f"{API_URL}/ai-posts/{dummy_post_id}/regenerate-content", json=content_data, headers=headers)
        
        if response.status_code == 403:
            results.log_success("AI Posts Regenerate Content Authentication (Regular User Forbidden)")
