def test_ai_posts_pagination_sorting():
    """Test that posts are sorted by created_at/published_at descending (latest first)"""
    if not admin_token:
        results.log_failure("AI Posts Pagination Sorting", "No admin token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {admin_token}"}
        
        # Test ready-to-publish posts (sorted by created_at descending)
        response = requests.get(f"{API_URL}/ai-posts/ready-to-publish?page=1&limit=10", headers=headers)
        if response.status_code == 200:
            data = response.json()
            posts = data.get("posts", [])
            
            if len(posts) > 1:
                # Check if posts are sorted by created_at descending
                for i in range(len(posts) - 1):
                    if "created_at" in posts[i] and "created_at" in posts[i + 1]:
                        current_date = posts[i]["created_at"]
                        next_date = posts[i + 1]["created_at"]
                        
                        # Compare dates (should be descending order)
                        if current_date < next_date:
                            results.log_failure("AI Posts Pagination Sorting", "Ready-to-publish posts not sorted by created_at descending")
                            return False
        
        # Test published posts (sorted by published_at descending)
        response = requests.get(f"{API_URL}/ai-posts/published?page=1&limit=10", headers=headers)
        if response.status_code == 200:
            data = response.json()
            posts = data.get("posts", [])
            
            if len(posts) > 1:
                # Check if posts are sorted by published_at descending
                for i in range(len(posts) - 1):
                    if "published_at" in posts[i] and "published_at" in posts[i + 1]:
                        current_date = posts[i]["published_at"]
                        next_date = posts[i + 1]["published_at"]
                        
                        # Compare dates (should be descending order)
                        if current_date < next_date:
                            results.log_failure("AI Posts Pagination Sorting", "Published posts not sorted by published_at descending")
                            return False
        
        results.log_success("AI Posts Pagination Sorting (Latest First)")
        return True
    except Exception as e:
        results.log_failure("AI Posts Pagination Sorting", str(e))
        return False

