def test_timezone_scheduled_posts_processing():
    """Test that scheduled posts are processed correctly with business timezone dates"""
    if not admin_token:
        results.log_failure("Timezone Scheduled Posts Processing", "No admin token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {admin_token}"}
        
        # Create a scheduled post for future processing
        from datetime import datetime, timedelta
        future_date = (datetime.now() + timedelta(minutes=2)).strftime("%Y-%m-%d")
        future_time = (datetime.now() + timedelta(minutes=2)).strftime("%H:%M")
        
        agent_data = {
            "mode": "adhoc",
            "topic": "Pet Nutrition",
            "word_count": "120",
            "social_platforms": {"facebook": True, "instagram": False, "twitter": False, "whatsapp": False},
            "image_option": "none",
            "post_destination": "auto_post",
            "post_date": future_date,
            "post_time": future_time,
            "immediate": False
        }
        
        response = requests.post(f"{API_URL}/ai-agents", json=agent_data, headers=headers)
        if response.status_code == 200:
            # Wait for post generation
            time.sleep(3)
            
            # Check if scheduled post was created with proper timezone handling
            ready_response = requests.get(f"{API_URL}/ai-posts/ready-to-publish", headers=headers)
            if ready_response.status_code == 200:
                ready_data = ready_response.json()
                
                # Look for scheduled posts
                scheduled_found = False
                for post in ready_data.get("posts", []):
                    if post.get("status") == "scheduled" and post.get("scheduled_for"):
                        scheduled_for = post["scheduled_for"]
                        
                        # Verify scheduled_for is in business timezone format
                        if not (isinstance(scheduled_for, str) and scheduled_for.endswith('Z')):
                            scheduled_found = True
                            results.log_success("Timezone Scheduled Posts Processing (Business Timezone)")
                            return True
                        else:
                            results.log_failure("Timezone Scheduled Posts Processing", f"scheduled_for in UTC format: {scheduled_for}")
                            return False
                
                if not scheduled_found:
                    # Check if post was published immediately (past time)
                    published_response = requests.get(f"{API_URL}/ai-posts/published", headers=headers)
                    if published_response.status_code == 200:
                        published_data = published_response.json()
                        if published_data.get("posts") and len(published_data["posts"]) > 0:
                            post = published_data["posts"][0]
                            if "published_at" in post and post["published_at"]:
                                published_at = post["published_at"]
                                if not (isinstance(published_at, str) and published_at.endswith('Z')):
                                    results.log_success("Timezone Scheduled Posts Processing (Immediate Publish - Business Timezone)")
                                    return True
                                else:
                                    results.log_failure("Timezone Scheduled Posts Processing", f"published_at in UTC format: {published_at}")
                                    return False
                    
                    results.log_failure("Timezone Scheduled Posts Processing", "No scheduled or published posts found")
                    return False
            else:
                results.log_failure("Timezone Scheduled Posts Processing", f"Failed to get ready posts: {ready_response.status_code}")
                return False
        else:
            results.log_failure("Timezone Scheduled Posts Processing", f"Status: {response.status_code}, Response: {response.text}")
            return False
            
    except Exception as e:
        results.log_failure("Timezone Scheduled Posts Processing", str(e))
        return False

