def test_regular_vs_after_hours_classification():
    """Test that regular vs after-hours classification works correctly"""
    if not manager_token:
        results.log_failure("Regular vs After Hours Classification", "No manager token available")
        return False
    
    try:
        # Create a test time entry that spans regular and after-hours
        from datetime import datetime, timedelta
        
        headers = {"Authorization": f"Bearer {manager_token}"}
        
        # First get the after hours cutoff time
        config_response = requests.get(f"{API_URL}/timesheet-config", headers=headers)
        if config_response.status_code != 200:
            results.log_failure("Regular vs After Hours Classification", "Could not get timesheet config")
            return False
        
        config = config_response.json()
        cutoff_time = config.get("after_hours_cutoff_time", "18:00")
        cutoff_hour = int(cutoff_time.split(":")[0])
        
        # Clock in before cutoff time
        clock_in_data = {
            "location_data": {"ip": "192.168.1.100", "source": "test"},
            "notes": f"Testing regular vs after-hours classification (cutoff: {cutoff_time})"
        }
        
        response = requests.post(f"{API_URL}/timesheet/clock-in", json=clock_in_data, headers=headers)
        
        if response.status_code == 200:
            time_entry_id = response.json()["time_entry_id"]
            
            # Wait a moment then clock out
            import time
            time.sleep(2)
            
            clock_out_response = requests.post(f"{API_URL}/timesheet/clock-out", 
                                             json={"notes": "Testing classification"}, 
                                             headers=headers)
            
            if clock_out_response.status_code == 200:
                data = clock_out_response.json()
                total_hours = data.get("total_hours", 0)
                regular_hours = data.get("regular_hours", 0)
                after_hours_hours = data.get("after_hours_hours", 0)
                
                # Get current hour to determine expected classification
                current_hour = datetime.now().hour
                
                if current_hour < cutoff_hour:
                    # Should be all regular hours
                    if regular_hours > 0 and after_hours_hours == 0:
                        results.log_success(f"Regular vs After Hours Classification (Before cutoff: {regular_hours}h regular, {after_hours_hours}h after-hours)")
                        return True
                    else:
                        results.log_failure("Regular vs After Hours Classification", f"Expected all regular hours before {cutoff_time}, got {regular_hours}h regular, {after_hours_hours}h after-hours")
                        return False
                else:
                    # Should be all after-hours
                    if after_hours_hours > 0 and regular_hours == 0:
                        results.log_success(f"Regular vs After Hours Classification (After cutoff: {regular_hours}h regular, {after_hours_hours}h after-hours)")
                        return True
                    else:
                        results.log_success(f"Regular vs After Hours Classification (Mixed hours: {regular_hours}h regular, {after_hours_hours}h after-hours)")
                        return True
        
        results.log_failure("Regular vs After Hours Classification", f"Clock in/out failed: {response.status_code}")
        return False
    except Exception as e:
        results.log_failure("Regular vs After Hours Classification", str(e))
        return False

