def test_break_time_calculation():
    """Test that break time is properly subtracted from total hours"""
    if not manager_token:
        results.log_failure("Break Time Calculation", "No manager token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {manager_token}"}
        
        # Clock in
        clock_in_data = {
            "location_data": {"ip": "192.168.1.100", "source": "test"},
            "notes": "Testing break time calculation"
        }
        
        response = requests.post(f"{API_URL}/timesheet/clock-in", json=clock_in_data, headers=headers)
        
        if response.status_code == 200:
            time_entry_id = response.json()["time_entry_id"]
            
            # Work for 2 seconds
            import time
            time.sleep(2)
            
            # Start break
            break_start_response = requests.post(f"{API_URL}/timesheet/break-start", 
                                               json={"break_type": "break", "notes": "Test break"}, 
                                               headers=headers)
            
            if break_start_response.status_code == 200:
                # Break for 1 second
                time.sleep(1)
                
                # End break
                break_end_response = requests.post(f"{API_URL}/timesheet/break-end", 
                                                 json={"notes": "End test break"}, 
                                                 headers=headers)
                
                if break_end_response.status_code == 200:
                    # Work for another 2 seconds
                    time.sleep(2)
                    
                    # Clock out
                    clock_out_response = requests.post(f"{API_URL}/timesheet/clock-out", 
                                                     json={"notes": "Break calculation test"}, 
                                                     headers=headers)
                    
                    if clock_out_response.status_code == 200:
                        data = clock_out_response.json()
                        total_hours = data.get("total_hours", 0)
                        
                        # Should have ~4 seconds of work time (5 total - 1 break)
                        if total_hours > 0:
                            results.log_success(f"Break Time Calculation (Total hours with break: {total_hours})")
                            return True
                        else:
                            results.log_failure("Break Time Calculation", f"❌ Hours with break still shows {total_hours}")
                            return False
        
        results.log_failure("Break Time Calculation", "Failed to complete break workflow")
        return False
    except Exception as e:
        results.log_failure("Break Time Calculation", str(e))
        return False

