def test_timesheet_data_structure_verification():
    """Verify timesheet posts have correct data structure and content"""
    if not admin_token:
        results.log_failure("Timesheet Data Structure Verification", "No admin token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {admin_token}"}
        params = {"agent_type": "time_sheet"}
        response = requests.get(f"{API_URL}/ai-posts/ready-to-publish", headers=headers, params=params)
        
        if response.status_code == 200:
            data = response.json()
            if isinstance(data, dict) and "posts" in data:
                posts = data["posts"]
                
                if not posts:
                    print(f"\n📋 TIMESHEET DATA STRUCTURE:")
                    print(f"   No timesheet posts available for structure verification")
                    results.log_success("Timesheet Data Structure Verification - No Data to Verify")
                    return True
                
                print(f"\n📋 TIMESHEET DATA STRUCTURE VERIFICATION:")
                print(f"   Analyzing {len(posts)} timesheet posts...")
                
                # Required fields for timesheet posts
                required_fields = ["id", "agent_type", "status", "created_at"]
                optional_fields = ["content", "topic", "image_url", "image_text", "timesheet_data"]
                
                structure_valid = True
                for i, post in enumerate(posts[:3]):  # Check first 3 posts
                    print(f"\n   Post {i+1} (ID: {post.get('id', 'N/A')}):")
                    
                    # Check required fields
                    for field in required_fields:
                        if field in post:
                            print(f"     ✅ {field}: {str(post[field])[:50]}{'...' if len(str(post[field])) > 50 else ''}")
                        else:
                            print(f"     ❌ Missing required field: {field}")
                            structure_valid = False
                    
                    # Check optional fields
                    for field in optional_fields:
                        if field in post:
                            value = post[field]
                            if field == "timesheet_data" and isinstance(value, dict):
                                print(f"     ✅ {field}: Contains timesheet data structure")
                            else:
                                print(f"     ✅ {field}: {str(value)[:50]}{'...' if len(str(value)) > 50 else ''}")
                    
                    # Verify agent_type is correct
                    if post.get("agent_type") != "time_sheet":
                        print(f"     ❌ Incorrect agent_type: {post.get('agent_type')}")
                        structure_valid = False
                
                if structure_valid:
                    results.log_success("Timesheet Data Structure Verification - Valid Structure")
                else:
                    results.log_failure("Timesheet Data Structure Verification", "Invalid data structure found")
                return structure_valid
            else:
                results.log_failure("Timesheet Data Structure Verification", f"Unexpected response format: {data}")
                return False
        else:
            results.log_failure("Timesheet Data Structure Verification", f"Status: {response.status_code}, Response: {response.text}")
            return False
    except Exception as e:
        results.log_failure("Timesheet Data Structure Verification", str(e))
        return False

