def test_timesheet_agent_collection_mismatch():
    """Test for collection mismatch between ai_agents and timesheet_ai_agents"""
    if not admin_token:
        results.log_failure("Timesheet Agent Collection Mismatch", "No admin token available")
        return False
    
    try:
        print(f"\n🔍 TIMESHEET AGENT COLLECTION MISMATCH INVESTIGATION:")
        print("="*60)
        
        headers = {"Authorization": f"Bearer {admin_token}"}
        
        # Get agents from both collections
        print("1. Getting agents from ai_agents collection...")
        response1 = requests.get(f"{API_URL}/ai-agents", headers=headers)
        
        print("2. Getting agents from timesheet-ai-agents collection...")
        response2 = requests.get(f"{API_URL}/timesheet-ai-agents", headers=headers)
        
        if response1.status_code != 200:
            results.log_failure("Collection Mismatch - AI Agents", f"Status: {response1.status_code}")
            return False
        
        if response2.status_code != 200:
            print(f"   Warning: timesheet-ai-agents endpoint failed: {response2.status_code}")
            timesheet_ai_agents = []
        else:
            timesheet_ai_agents = response2.json()
        
        ai_agents = response1.json()
        timesheet_agents_main = [agent for agent in ai_agents if agent.get('agent_type') == 'time_sheet']
        
        print(f"   AI Agents collection - Total agents: {len(ai_agents)}")
        print(f"   AI Agents collection - Timesheet agents: {len(timesheet_agents_main)}")
        print(f"   Timesheet AI Agents collection - Total agents: {len(timesheet_ai_agents)}")
        
        # Check for ID overlaps and differences
        main_ids = set(agent.get('id') for agent in timesheet_agents_main)
        timesheet_ids = set(agent.get('id') for agent in timesheet_ai_agents)
        
        print(f"\n3. Collection comparison:")
        print(f"   IDs in ai_agents (timesheet type): {len(main_ids)}")
        print(f"   IDs in timesheet-ai-agents: {len(timesheet_ids)}")
        
        common_ids = main_ids.intersection(timesheet_ids)
        only_in_main = main_ids - timesheet_ids
        only_in_timesheet = timesheet_ids - main_ids
        
        print(f"   Common IDs: {len(common_ids)}")
        print(f"   Only in ai_agents: {len(only_in_main)}")
        print(f"   Only in timesheet-ai-agents: {len(only_in_timesheet)}")
        
        if only_in_main:
            print(f"   ❌ COLLECTION MISMATCH DETECTED!")
            print(f"   Agents in ai_agents but not in timesheet-ai-agents: {list(only_in_main)}")
        
        if only_in_timesheet:
            print(f"   ❌ COLLECTION MISMATCH DETECTED!")
            print(f"   Agents in timesheet-ai-agents but not in ai_agents: {list(only_in_timesheet)}")
        
        # Test update operations on agents from different collections
        if timesheet_agents_main:
            print(f"\n4. Testing update operations:")
            test_agent = timesheet_agents_main[0]
            agent_id = test_agent.get('id')
            
            update_data = {
                "name": test_agent.get('name', 'Test Agent'),
                "workflow_mode": "adhoc",
                "selected_employees": ["test_user"],
                "email_recipients": ["test@example.com"]
            }
            
            # Try updating via main ai-agents endpoint
            print(f"   Testing update via /ai-agents/{agent_id}...")
            response = requests.put(f"{API_URL}/ai-agents/{agent_id}", json=update_data, headers=headers)
            print(f"   Result: {response.status_code}")
            
            # Try updating via timesheet-ai-agents endpoint
            print(f"   Testing update via /timesheet-ai-agents/{agent_id}...")
            response = requests.put(f"{API_URL}/timesheet-ai-agents/{agent_id}", json=update_data, headers=headers)
            print(f"   Result: {response.status_code}")
            
            if response.status_code == 404:
                print(f"   ❌ CRITICAL: Agent exists in ai_agents but update via timesheet-ai-agents returns 404!")
                print(f"   This confirms the collection mismatch issue!")
        
        results.log_success("Timesheet Agent Collection Mismatch Investigation")
        return True
        
    except Exception as e:
        results.log_failure("Timesheet Agent Collection Mismatch", str(e))
        return False

