def test_recurring_email_agent_data_structure():
    """Test 5: Verify Recurring Email Agent data structure and retrieval"""
    if not admin_token or not created_email_agent_id:
        results.log_failure("Recurring Email Agent Data Structure", "No admin token or created agent ID available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {admin_token}"}
        
        # Retrieve the created email agent to verify data structure
        response = requests.get(f"{API_URL}/ai-agents", headers=headers)
        
        if response.status_code == 200:
            agents = response.json()
            if isinstance(agents, list):
                # Find our created agent
                created_agent = None
                for agent in agents:
                    if agent.get("id") == created_email_agent_id:
                        created_agent = agent
                        break
                
                if created_agent:
                    # Verify core required fields are present
                    core_fields = [
                        "agent_type", "mode", "agent_name", "topic", 
                        "schedule_type", "days_of_week", "post_time"
                    ]
                    
                    missing_core_fields = []
                    for field in core_fields:
                        if field not in created_agent:
                            missing_core_fields.append(field)
                    
                    if not missing_core_fields:
                        # Verify specific values
                        if (created_agent.get("agent_type") == "email" and
                            created_agent.get("mode") == "recurring" and
                            created_agent.get("schedule_type") == "weekly" and
                            created_agent.get("topic") == "Pet Health Tips"):
                            
                            # Check if optional fields exist (they might be stored differently)
                            optional_fields_present = 0
                            optional_fields = ["business_info", "email_content_template", "use_chatgpt_formatting", "use_customer_database"]
                            for field in optional_fields:
                                if field in created_agent:
                                    optional_fields_present += 1
                            
                            results.log_success(f"Recurring Email Agent Data Structure (Core Fields Complete, {optional_fields_present}/{len(optional_fields)} Optional Fields Present)")
                            return True
                        else:
                            results.log_failure("Recurring Email Agent Data Structure", "Core field values don't match expected")
                            return False
                    else:
                        results.log_failure("Recurring Email Agent Data Structure", f"Missing core fields: {missing_core_fields}")
                        return False
                else:
                    results.log_failure("Recurring Email Agent Data Structure", "Created agent not found in list")
                    return False
            else:
                results.log_failure("Recurring Email Agent Data Structure", "Response is not a list")
                return False
        
        results.log_failure("Recurring Email Agent Data Structure", f"Status: {response.status_code}, Response: {response.text}")
        return False
    except Exception as e:
        results.log_failure("Recurring Email Agent Data Structure", str(e))
        return False

