def test_ai_agent_creation_with_post_destination():
    """Test AI agent creation with post_destination field"""
    if not admin_token:
        results.log_failure("AI Agent Creation with Post Destination", "No admin token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {admin_token}"}
        
        # Test agent with in_review destination
        agent_data_in_review = {
            "agent_name": "Test In Review Agent",
            "mode": "adhoc",
            "topic": "Pet Health Tips",
            "agent_type": "social_media",
            "word_count": "150",
            "image_option": "none",
            "image_text": "Healthy pets playing",
            "social_platforms": {
                "facebook": True,
                "instagram": True,
                "twitter": False,
                "whatsapp": False
            },
            "post_destination": "in_review",
            "immediate": False
        }
        
        response = requests.post(f"{API_URL}/ai-agents", json=agent_data_in_review, headers=headers)
        if response.status_code == 200:
            data = response.json()
            if "agent_id" in data and "message" in data:
                results.log_success("AI Agent Creation with In Review Destination")
                
                # Test agent with ready_to_publish destination
                agent_data_ready = {
                    "agent_name": "Test Ready to Publish Agent",
                    "mode": "adhoc",
                    "topic": "Pet Nutrition",
                    "agent_type": "social_media",
                    "word_count": "200",
                    "image_option": "none",
                    "image_text": "Nutritious pet food",
                    "social_platforms": {
                        "facebook": True,
                        "instagram": False,
                        "twitter": True,
                        "whatsapp": False
                    },
                    "post_destination": "ready_to_publish",
                    "immediate": False
                }
                
                response2 = requests.post(f"{API_URL}/ai-agents", json=agent_data_ready, headers=headers)
                if response2.status_code == 200:
                    data2 = response2.json()
                    if "agent_id" in data2:
                        results.log_success("AI Agent Creation with Ready to Publish Destination")
                        return True
                        
        results.log_failure("AI Agent Creation with Post Destination", f"Status: {response.status_code}, Response: {response.text}")
        return False
    except Exception as e:
        results.log_failure("AI Agent Creation with Post Destination", str(e))
        return False

def test_get_in_review_posts():
    """Test GET /api/ai-posts/in-review endpoint with pagination"""
    if not admin_token:
        results.log_failure("Get In Review Posts", "No admin token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {admin_token}"}
        
        # Test basic in-review endpoint
        response = requests.get(f"{API_URL}/ai-posts/in-review", headers=headers)
        if response.status_code == 200:
            data = response.json()
            if ("posts" in data and "pagination" in data and 
                "current_page" in data["pagination"] and 
                "total_pages" in data["pagination"] and
                "total_count" in data["pagination"]):
                results.log_success("Get In Review Posts - Basic")
                
                # Test with pagination parameters
                response2 = requests.get(f"{API_URL}/ai-posts/in-review?page=1&limit=5", headers=headers)
                if response2.status_code == 200:
                    data2 = response2.json()
                    if (data2["pagination"]["limit"] == 5 and 
                        data2["pagination"]["current_page"] == 1):
                        results.log_success("Get In Review Posts - Pagination")
                        
                        # Test with agent type filter
                        response3 = requests.get(f"{API_URL}/ai-posts/in-review?agent_type=social_media", headers=headers)
                        if response3.status_code == 200:
                            results.log_success("Get In Review Posts - Agent Type Filter")
                            return True
                            
        results.log_failure("Get In Review Posts", f"Status: {response.status_code}, Response: {response.text}")
        return False
    except Exception as e:
        results.log_failure("Get In Review Posts", str(e))
        return False

