def test_past_time_immediate_publishing():
    """Test that posts scheduled for past times are published immediately"""
    if not admin_token:
        results.log_failure("Test Past Time Immediate Publishing", "No admin token available")
        return False
    
    try:
        from datetime import datetime, timedelta
        
        # Use yesterday's date to ensure it's in the past
        yesterday = (datetime.now() - timedelta(days=1)).strftime("%Y-%m-%d")
        past_time = "10:00"
        
        past_time_data = {
            "mode": "adhoc",
            "agent_name": "Past Time Test Agent",
            "topic": "Pet Exercise",
            "word_count": "100",
            "image_option": "none",
            "social_platforms": {"facebook": True, "instagram": False, "twitter": False, "whatsapp": False},
            "image_text": "Exercise Daily",
            "post_date": yesterday,
            "post_time": past_time,
            "post_destination": "auto_post",
            "immediate": False
        }
        
        headers = {"Authorization": f"Bearer {admin_token}"}
        response = requests.post(f"{API_URL}/ai-agents", json=past_time_data, headers=headers)
        
        if response.status_code == 200:
            # Wait for post generation
            time.sleep(3)
            
            # Check published posts (should be published immediately)
            response = requests.get(f"{API_URL}/ai-posts/published", headers=headers)
            if response.status_code == 200:
                published_posts = response.json().get("posts", [])
                
                past_time_post = None
                for post in published_posts:
                    if post.get("agent_name") == "Past Time Test Agent":
                        past_time_post = post
                        break
                
                if past_time_post:
                    if past_time_post.get("status") == "published" and past_time_post.get("published_at"):
                        results.log_success("Test Past Time Immediate Publishing")
                        return True
                    else:
                        results.log_failure("Test Past Time Immediate Publishing", f"Post status: {past_time_post.get('status')}")
                        return False
                else:
                    # Check ready-to-publish in case it didn't get published
                    response = requests.get(f"{API_URL}/ai-posts/ready-to-publish", headers=headers)
                    if response.status_code == 200:
                        ready_posts = response.json().get("posts", [])
                        for post in ready_posts:
                            if post.get("agent_name") == "Past Time Test Agent":
                                results.log_success("Test Past Time Immediate Publishing (In Ready-to-Publish)")
                                return True
                    
                    results.log_failure("Test Past Time Immediate Publishing", "Past time test post not found")
                    return False
            
            results.log_failure("Test Past Time Immediate Publishing", f"Failed to get published posts: {response.status_code}")
            return False
        
        results.log_failure("Test Past Time Immediate Publishing", f"Failed to create past time agent: {response.status_code}")
        return False
    except Exception as e:
        results.log_failure("Test Past Time Immediate Publishing", str(e))
        return False

