def run_scheduled_auto_posting_tests():
    """Run comprehensive tests for scheduled auto-posting functionality"""
    print(f"\n{'='*80}")
    print(f"🕐 SCHEDULED AUTO-POSTING FUNCTIONALITY TESTS")
    print(f"{'='*80}")
    
    # First, ensure we have admin authentication
    if not test_admin_login():
        print("❌ Cannot proceed without admin authentication")
        return False
    
    # Run scheduled auto-posting tests in order
    scheduled_tests = [
        test_create_adhoc_scheduled_agent,
        test_verify_scheduled_post_created,
        test_timezone_conversion_functionality,
        test_past_time_immediate_publishing,
        test_background_scheduler_running,
        test_different_timezone_scheduling,
        test_scheduled_post_status_transitions
    ]
    
    scheduled_passed = 0
    scheduled_failed = 0
    
    for test_func in scheduled_tests:
        try:
            if test_func():
                scheduled_passed += 1
            else:
                scheduled_failed += 1
        except Exception as e:
            print(f"❌ Test {test_func.__name__} crashed: {str(e)}")
            scheduled_failed += 1
    
    print(f"\n{'='*80}")
    print(f"🕐 SCHEDULED AUTO-POSTING TEST SUMMARY")
    print(f"{'='*80}")
    print(f"Scheduled Tests Passed: {scheduled_passed}")
    print(f"Scheduled Tests Failed: {scheduled_failed}")
    
    if scheduled_failed == 0:
        print(f"\n✅ ALL SCHEDULED AUTO-POSTING TESTS PASSED!")
        print(f"   - Adhoc agents with auto_post + date/time create scheduled posts")
        print(f"   - Timezone conversion working correctly")
        print(f"   - Background scheduler processing posts")
        print(f"   - Past times publish immediately")
        print(f"   - Future times get scheduled status")
    else:
        print(f"\n❌ SOME SCHEDULED AUTO-POSTING TESTS FAILED:")
        print(f"   Please check the specific test failures above")
    
    return scheduled_failed == 0

