def test_manager_clock_in_investigation():
    """Test POST /api/timesheet/clock-in with manager credentials - INVESTIGATION"""
    if not manager_token:
        results.log_failure("Manager Clock In Investigation", "No manager token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {manager_token}"}
        
        # First check if manager is already clocked in
        status_response = requests.get(f"{API_URL}/timesheet/status", headers=headers)
        if status_response.status_code == 200:
            status_data = status_response.json()
            if status_data.get("is_clocked_in"):
                # Clock out first
                requests.post(f"{API_URL}/timesheet/clock-out", headers=headers)
                time.sleep(1)  # Wait a moment
        
        # Now test clock in
        clock_in_data = {
            "location_data": {"ip": "192.168.1.100", "location": "Main Office"},
            "notes": "Manager investigation test - clock in"
        }
        
        response = requests.post(f"{API_URL}/timesheet/clock-in", json=clock_in_data, headers=headers)
        
        if response.status_code == 200:
            data = response.json()
            if (data.get("user_id") and 
                data.get("clock_in_time") and 
                data.get("status") == "active" and
                "id" in data):
                results.log_success("Manager Clock In Investigation - Entry Created Successfully")
                print(f"   📝 Clock In Entry ID: {data['id']}")
                print(f"   👤 User ID: {data['user_id']}")
                print(f"   🕐 Clock In Time: {data['clock_in_time']}")
                return True
        
        results.log_failure("Manager Clock In Investigation", f"Status: {response.status_code}, Response: {response.text}")
        return False
    except Exception as e:
        results.log_failure("Manager Clock In Investigation", str(e))
        return False

