def test_manager_real_time_status_investigation():
    """Test real-time status updates for manager - INVESTIGATION"""
    if not manager_token:
        results.log_failure("Manager Real-time Status Investigation", "No manager token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {manager_token}"}
        
        print("   🔄 Testing real-time status workflow...")
        
        # Step 1: Check initial status
        initial_status = requests.get(f"{API_URL}/timesheet/status", headers=headers)
        if initial_status.status_code == 200:
            initial_data = initial_status.json()
            print(f"   📊 Initial Status - Clocked In: {initial_data.get('is_clocked_in')}")
            
            # If clocked in, clock out first
            if initial_data.get("is_clocked_in"):
                requests.post(f"{API_URL}/timesheet/clock-out", headers=headers)
                time.sleep(1)
        
        # Step 2: Clock in and check status immediately
        clock_in_response = requests.post(f"{API_URL}/timesheet/clock-in", 
                                        json={"notes": "Real-time status test"}, 
                                        headers=headers)
        
        if clock_in_response.status_code == 200:
            print(f"   ✅ Clock in successful")
            
            # Check status immediately after clock in
            immediate_status = requests.get(f"{API_URL}/timesheet/status", headers=headers)
            if immediate_status.status_code == 200:
                immediate_data = immediate_status.json()
                print(f"   📊 Immediate Status - Clocked In: {immediate_data.get('is_clocked_in')}")
                print(f"   ⏰ Daily Hours: {immediate_data.get('daily_hours')}")
                
                if immediate_data.get("is_clocked_in"):
                    # Wait and check status again
                    time.sleep(2)
                    updated_status = requests.get(f"{API_URL}/timesheet/status", headers=headers)
                    if updated_status.status_code == 200:
                        updated_data = updated_status.json()
                        print(f"   📊 Updated Status - Daily Hours: {updated_data.get('daily_hours')}")
                        
                        # Clock out and check final status
                        clock_out_response = requests.post(f"{API_URL}/timesheet/clock-out", headers=headers)
                        if clock_out_response.status_code == 200:
                            final_status = requests.get(f"{API_URL}/timesheet/status", headers=headers)
                            if final_status.status_code == 200:
                                final_data = final_status.json()
                                print(f"   📊 Final Status - Clocked In: {final_data.get('is_clocked_in')}")
                                
                                results.log_success("Manager Real-time Status Investigation - Status Updates Working")
                                return True
        
        results.log_failure("Manager Real-time Status Investigation", "Status workflow failed")
        return False
    except Exception as e:
        results.log_failure("Manager Real-time Status Investigation", str(e))
        return False

def test_timesheet_reports_zero_regular_hours():
    """Test GET /api/timesheet/reports endpoint - CRITICAL ISSUE INVESTIGATION"""
    if not manager_token:
        results.log_failure("Timesheet Reports Zero Regular Hours", "No manager token available")
        return False
    
    try:
        # Test with a date range that should have time entries
        from datetime import datetime, timedelta
        end_date = datetime.now().strftime("%Y-%m-%d")
        start_date = (datetime.now() - timedelta(days=30)).strftime("%Y-%m-%d")
        
        headers = {"Authorization": f"Bearer {manager_token}"}
        response = requests.get(
            f"{API_URL}/timesheet/reports",
            params={"start_date": start_date, "end_date": end_date},
            headers=headers
        )
        
        if response.status_code == 200:
            data = response.json()
            
            # Check response structure
            required_fields = ["period", "reports", "total_employees", "total_hours", "total_pay"]
            if not all(field in data for field in required_fields):
                results.log_failure("Timesheet Reports Zero Regular Hours", f"Missing required fields in response: {data.keys()}")
                return False
            
            # Check if we have any reports
            reports = data.get("reports", [])
            if not reports:
                results.log_success("Timesheet Reports Zero Regular Hours (No Data - Expected)")
                return True
            
            # CRITICAL CHECK: Examine regular hours vs total hours
            critical_issues = []
            for report in reports:
                user_name = report.get("user_name", "Unknown")
                total_hours = report.get("total_hours", 0)
                regular_hours = report.get("regular_hours", 0)
                after_hours = report.get("after_hours_hours", 0)
                
                # CRITICAL ISSUE: Regular hours showing as zero despite total hours
                if total_hours > 0 and regular_hours == 0:
                    critical_issues.append(f"❌ CRITICAL: {user_name} has {total_hours} total hours but 0 regular hours!")
                
                # Check if hours add up correctly
                calculated_total = regular_hours + after_hours
                if abs(calculated_total - total_hours) > 0.01:  # Allow small rounding differences
                    critical_issues.append(f"⚠️ WARNING: {user_name} hours don't add up: regular({regular_hours}) + after_hours({after_hours}) = {calculated_total} != total({total_hours})")
            
            if critical_issues:
                results.log_failure("Timesheet Reports Zero Regular Hours", f"CRITICAL ISSUES FOUND: {'; '.join(critical_issues)}")
                return False
            else:
                results.log_success("Timesheet Reports Zero Regular Hours (Hours Breakdown Correct)")
                return True
                
        results.log_failure("Timesheet Reports Zero Regular Hours", f"Status: {response.status_code}, Response: {response.text}")
        return False
    except Exception as e:
        results.log_failure("Timesheet Reports Zero Regular Hours", str(e))
        return False

def test_time_entry_hours_calculation():
    """Test actual time entries to verify hours calculation is working"""
    if not manager_token:
        results.log_failure("Time Entry Hours Calculation", "No manager token available")
        return False
    
    try:
        # Get all time entries to examine their structure
        from datetime import datetime, timedelta
        end_date = datetime.now().strftime("%Y-%m-%d")
        start_date = (datetime.now() - timedelta(days=30)).strftime("%Y-%m-%d")
        
        headers = {"Authorization": f"Bearer {manager_token}"}
        response = requests.get(
            f"{API_URL}/timesheet/all-entries",
            params={"start_date": start_date, "end_date": end_date},
            headers=headers
        )
        
        if response.status_code == 200:
            entries = response.json()
            
            if not entries:
                results.log_success("Time Entry Hours Calculation (No Entries Found)")
                return True
            
            # Examine structure of time entries
            structure_issues = []
            completed_entries = 0
            zero_hour_entries = 0
            
            for entry in entries:
                entry_id = entry.get("id", "Unknown")
                
                # Check if entry is completed (has clock_out_time)
                if entry.get("clock_out_time") and entry.get("status") in ["completed", "adjusted"]:
                    completed_entries += 1
                    
                    # Check if hours are calculated
                    total_hours = entry.get("total_hours", 0)
                    regular_hours = entry.get("regular_hours", 0)
                    after_hours = entry.get("after_hours_hours", 0)
                    
                    if total_hours == 0:
                        zero_hour_entries += 1
                        # Check if this is a very short entry (less than a minute)
                        clock_in = entry.get("clock_in_time")
                        clock_out = entry.get("clock_out_time")
                        if clock_in and clock_out:
                            from datetime import datetime
                            try:
                                in_time = datetime.fromisoformat(clock_in.replace("Z", "+00:00"))
                                out_time = datetime.fromisoformat(clock_out.replace("Z", "+00:00"))
                                duration_seconds = (out_time - in_time).total_seconds()
                                if duration_seconds > 60:  # More than 1 minute should have some hours
                                    structure_issues.append(f"❌ CRITICAL Entry {entry_id}: {duration_seconds}s duration but 0 total hours!")
                            except:
                                structure_issues.append(f"Entry {entry_id}: Cannot parse timestamps")
                    
                    # CRITICAL ISSUE CHECK: Regular hours zero despite working
                    if total_hours > 0 and regular_hours == 0:
                        structure_issues.append(f"❌ CRITICAL Entry {entry_id}: {total_hours} total hours but 0 regular hours!")
            
            if structure_issues:
                results.log_failure("Time Entry Hours Calculation", f"Issues found: {'; '.join(structure_issues[:3])}...")
                return False
            else:
                results.log_success(f"Time Entry Hours Calculation (Examined {len(entries)} entries, {completed_entries} completed, {zero_hour_entries} zero-hour)")
                return True
                
        results.log_failure("Time Entry Hours Calculation", f"Status: {response.status_code}, Response: {response.text}")
        return False
    except Exception as e:
        results.log_failure("Time Entry Hours Calculation", str(e))
        return False

def test_after_hours_cutoff_configuration():
    """Test timesheet configuration to verify after_hours_cutoff_time setting"""
    if not manager_token:
        results.log_failure("After Hours Cutoff Configuration", "No manager token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {manager_token}"}
        response = requests.get(f"{API_URL}/timesheet-config", headers=headers)
        
        if response.status_code == 200:
            config = response.json()
            
            # Check if after_hours_cutoff_time is properly configured
            after_hours_cutoff = config.get("after_hours_cutoff_time")
            if not after_hours_cutoff:
                results.log_failure("After Hours Cutoff Configuration", "❌ CRITICAL: after_hours_cutoff_time not configured!")
                return False
            
            # Validate format (should be HH:MM)
            try:
                hour, minute = map(int, after_hours_cutoff.split(":"))
                if 0 <= hour <= 23 and 0 <= minute <= 59:
                    results.log_success(f"After Hours Cutoff Configuration (Set to {after_hours_cutoff})")
                    return True
                else:
                    results.log_failure("After Hours Cutoff Configuration", f"Invalid time format: {after_hours_cutoff}")
                    return False
            except ValueError:
                results.log_failure("After Hours Cutoff Configuration", f"Invalid time format: {after_hours_cutoff}")
                return False
                
        results.log_failure("After Hours Cutoff Configuration", f"Status: {response.status_code}, Response: {response.text}")
        return False
    except Exception as e:
        results.log_failure("After Hours Cutoff Configuration", str(e))
        return False

