def test_timesheet_report_workflow_states():
    """Test timesheet report workflow states (in_review → ready_to_publish → published)"""
    if not admin_token:
        results.log_failure("Timesheet Report Workflow States", "No admin token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {admin_token}"}
        
        # Create a test agent for workflow testing
        agent_data = {
            "agent_name": "Workflow Test Agent",
            "mode": "adhoc",
            "report_period": "current_week",
            "initial_status": "in_review"
        }
        
        response = requests.post(f"{API_URL}/timesheet-ai-agents", json=agent_data, headers=headers)
        if response.status_code != 200:
            results.log_failure("Timesheet Report Workflow States (Setup)", "Failed to create test agent")
            return False
        
        agent_id = response.json()["agent_id"]
        
        # Run the agent to generate a report
        response = requests.post(f"{API_URL}/timesheet-ai-agents/{agent_id}/run", headers=headers)
        if response.status_code != 200:
            results.log_failure("Timesheet Report Workflow States (Generate)", "Failed to generate report")
            return False
        
        report_id = response.json()["report_id"]
        
        # Test workflow transitions: in_review → ready_to_publish → published
        transitions = [
            ("ready_to_publish", "Ready to Publish"),
            ("published", "Published")
        ]
        
        for status, status_name in transitions:
            status_data = {"status": status}
            response = requests.put(f"{API_URL}/timesheet-reports/{report_id}/status", 
                                  json=status_data, headers=headers)
            if response.status_code != 200:
                results.log_failure("Timesheet Report Workflow States", f"Failed to transition to {status_name}")
                return False
        
        results.log_success("Timesheet Report Workflow States")
        return True
    except Exception as e:
        results.log_failure("Timesheet Report Workflow States", str(e))
        return False

