def test_field_name_mismatch_investigation():
    """Investigate potential field name mismatches between frontend expectations and backend storage"""
    if not manager_token:
        results.log_failure("Field Name Mismatch Investigation", "No manager token available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {manager_token}"}
        
        # Get all timesheet agents to examine field names
        response = requests.get(f"{API_URL}/timesheet-ai-agents", headers=headers)
        
        if response.status_code == 200:
            agents = response.json()
            
            print(f"   🔍 Field Name Mismatch Investigation:")
            print(f"   📊 Total timesheet agents: {len(agents)}")
            
            if agents:
                # Check the first agent for field names
                sample_agent = agents[0]
                
                # Expected field names based on the model
                expected_fields = {
                    'selected_employees': 'List of employee user IDs',
                    'email_recipients': 'List of email addresses',
                    'agent_name': 'Agent name',
                    'mode': 'Agent mode (recurring/adhoc)',
                    'report_period': 'Report period type',
                    'include_summary': 'Include summary flag',
                    'include_billing_rates': 'Include billing rates flag',
                    'auto_email': 'Auto email flag'
                }
                
                print(f"   🔍 Field presence check:")
                missing_fields = []
                present_fields = []
                
                for field, description in expected_fields.items():
                    if field in sample_agent:
                        present_fields.append(field)
                        value = sample_agent[field]
                        print(f"      ✅ {field}: {value} ({description})")
                    else:
                        missing_fields.append(field)
                        print(f"      ❌ {field}: MISSING ({description})")
                
                # Check for any unexpected field names that might be variations
                all_fields = set(sample_agent.keys())
                expected_set = set(expected_fields.keys())
                unexpected_fields = all_fields - expected_set - {'id', 'created_at', 'updated_at', 'created_by', 'is_active'}
                
                if unexpected_fields:
                    print(f"   ⚠️  Unexpected fields found: {list(unexpected_fields)}")
                    for field in unexpected_fields:
                        print(f"      - {field}: {sample_agent[field]}")
                
                # Look for potential field name variations
                potential_variations = {
                    'selected_employees': ['employees', 'employee_ids', 'selected_employee_ids', 'employee_list'],
                    'email_recipients': ['emails', 'recipient_emails', 'email_list', 'recipients']
                }
                
                print(f"   🔍 Checking for field name variations:")
                for expected_field, variations in potential_variations.items():
                    if expected_field not in sample_agent:
                        for variation in variations:
                            if variation in sample_agent:
                                print(f"      ⚠️  Found variation: '{variation}' instead of '{expected_field}' = {sample_agent[variation]}")
                
                if missing_fields:
                    results.log_failure("Field Name Mismatch Investigation", f"Missing critical fields: {missing_fields}")
                    return False
                else:
                    results.log_success("Field Name Mismatch Investigation - All Expected Fields Present")
                    return True
            else:
                results.log_success("Field Name Mismatch Investigation - No Agents to Examine")
                return True
        else:
            results.log_failure("Field Name Mismatch Investigation", f"Status: {response.status_code}, Response: {response.text}")
            return False
    except Exception as e:
        results.log_failure("Field Name Mismatch Investigation", str(e))
        return False

def test_timesheet_agent_edit_form_data_population():
    """Test that timesheet agent data properly populates edit forms by examining API response structure"""
    if not manager_token or not created_timesheet_agent_id:
        results.log_failure("Timesheet Agent Edit Form Data Population", "No manager token or agent ID available")
        return False
    
    try:
        headers = {"Authorization": f"Bearer {manager_token}"}
        
        # Get the specific timesheet agent that we created/updated
        response = requests.get(f"{API_URL}/timesheet-ai-agents", headers=headers)
        
        if response.status_code == 200:
            agents = response.json()
            target_agent = None
            
            for agent in agents:
                if agent.get("id") == created_timesheet_agent_id:
                    target_agent = agent
                    break
            
            if target_agent:
                print(f"   🔍 Edit Form Data Population Test:")
                print(f"   📝 Agent ID: {target_agent.get('id')}")
                
                # Check that all fields needed for edit form are present and properly formatted
                form_fields = {
                    'agent_name': 'text input',
                    'selected_employees': 'multi-select dropdown',
                    'email_recipients': 'email input list',
                    'mode': 'radio/select',
                    'report_period': 'select dropdown',
                    'include_summary': 'checkbox',
                    'include_billing_rates': 'checkbox',
                    'auto_email': 'checkbox'
                }
                
                all_fields_valid = True
                
                for field, form_type in form_fields.items():
                    value = target_agent.get(field)
                    if value is not None:
                        print(f"      ✅ {field}: {value} (for {form_type})")
                        
                        # Validate data types for form population
                        if field in ['selected_employees', 'email_recipients']:
                            if not isinstance(value, list):
                                print(f"         ⚠️  Expected list for {field}, got {type(value)}")
                                all_fields_valid = False
                        elif field in ['include_summary', 'include_billing_rates', 'auto_email']:
                            if not isinstance(value, bool):
                                print(f"         ⚠️  Expected boolean for {field}, got {type(value)}")
                                all_fields_valid = False
                        elif field in ['agent_name', 'mode', 'report_period']:
                            if not isinstance(value, str):
                                print(f"         ⚠️  Expected string for {field}, got {type(value)}")
                                all_fields_valid = False
                    else:
                        print(f"      ❌ {field}: NULL/MISSING (needed for {form_type})")
                        all_fields_valid = False
                
                # Test specific scenarios that might cause frontend issues
                print(f"   🔍 Frontend Integration Checks:")
                
                # Check if selected_employees is empty vs null
                selected_employees = target_agent.get('selected_employees')
                if selected_employees is None:
                    print(f"      ⚠️  selected_employees is null - frontend might not handle this")
                elif len(selected_employees) == 0:
                    print(f"      ✅ selected_employees is empty list - should show 'All Employees'")
                else:
                    print(f"      ✅ selected_employees has {len(selected_employees)} items")
                
                # Check if email_recipients is empty vs null
                email_recipients = target_agent.get('email_recipients')
                if email_recipients is None:
                    print(f"      ⚠️  email_recipients is null - frontend might not handle this")
                elif len(email_recipients) == 0:
                    print(f"      ✅ email_recipients is empty list")
                else:
                    print(f"      ✅ email_recipients has {len(email_recipients)} items")
                
                if all_fields_valid:
                    results.log_success("Timesheet Agent Edit Form Data Population - All Fields Valid for Frontend")
                    return True
                else:
                    results.log_failure("Timesheet Agent Edit Form Data Population", "Some fields have invalid data types for frontend")
                    return False
            else:
                results.log_failure("Timesheet Agent Edit Form Data Population", "Target agent not found")
                return False
        else:
            results.log_failure("Timesheet Agent Edit Form Data Population", f"Status: {response.status_code}, Response: {response.text}")
            return False
    except Exception as e:
        results.log_failure("Timesheet Agent Edit Form Data Population", str(e))
        return False

